sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    var nonBusinessLiveMarkets = gs.getProperty("x_hsb11_mss_c_swft.mss.custody.nonBusinessLiveMarkets");
    //gs.info("================nonBusinessLiveMarkets===============" + nonBusinessLiveMarkets);

	/**
	 * MSSCUSTODY-5421
	 *  if Trade Reference is empty then put "Holding Search Screen" as the value of Trade ID field in the alert.
	 */
	var tradeId="";
	if (current.trade_reference == "") {
         tradeId = "Holding Search Screen";
    }
	else
	{
		tradeId=current.trade_reference.trade_id;
	}
    var region = tradeId.substring(0, 2);

    if (nonBusinessLiveMarkets.indexOf(region) === -1) {
        var failureDescription = "MSS Custody Swift Ondemand Staging failure, details of the error are as below ServiceNow Reference: " + current.trade_reference + " Trade ID : " + tradeId + " Timestamp : " + current.response_date + "Error code: " + current.response_code + "Error Body: " + current.response_body; //MSSCUSTODY-5421
        var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_EventLayer');
    }

})(current, previous);
